{
  "root_causes": [
    {
      "service": "ts-price-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind, count(*) n, sum(CASE WHEN duration/1e6 > 1000 THEN 1 ELSE 0 END) slow_over_1s, approx_quantile(duration/1e6, 0.5) p50_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='POST' GROUP BY 1",
          "claim": "In the incident window, ts-basic-service POST client calls mostly complete in ~7 ms, but 18 of 103 exceed 1 s, versus none in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, min(time) first_t, max(time) last_t FROM abnormal_traces WHERE service_name='ts-price-service' GROUP BY 1",
          "claim": "ts-price-service emits no spans after 15:30:30 in the incident window, while its pod metrics (CPU, memory) stay normal, so requests from basic are not reaching it."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, avg(value) avg_flags, max(value) max_flags FROM normal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-basic-service%' AND attr_destination LIKE '%ts-price-service%' UNION ALL SELECT 'abnormal', avg(value), max(value) FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-basic-service%' AND attr_destination LIKE '%ts-price-service%'",
          "claim": "TCP flag packets on the ts-basic-service to ts-price-service connection roughly double, from about 356 to 674 per sample, in the incident window."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-basic-service' AND level='SEVERE' AND message LIKE '%ts-price-service%' GROUP BY 1,2",
          "claim": "ts-basic-service logs SEVERE I/O errors on POST requests to http://ts-price-service:8080, failing its queryForTravels requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-price-service",
      "to": "ts-basic-service",
