          "claim": "Calls from ts-route-plan-service to ts-travel-service stall at about 131 s p95 in the incident window."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
