          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6, 0.95) p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND s.service_name='ts-travel2-service' GROUP BY 1,2",
